};

export const idField = "sprint_id" as const;
export const titleField = "title" as const;
export const fieldLabels: Record<string, string> = {"label":"Label","description":"Description","placeholder":"Placeholder","status":"Status","state_history":"State history","allowed_transitions":"Allowed transitions","created_at":"Created at","updated_at":"Updated at","last_event":"Last event","last_event_at":"Last event at","searchQuery":"Search Query","searchActive":"Search Active","filters":"Filters","activeFilters":"Active Filters","filterCount":"Filter Count","page":"Page","pageSize":"Page Size","totalItems":"Total Items","totalPages":"Total Pages","sprint_id":"Sprint id","title":"Title","focus":"Focus","start_date":"Start date","end_date":"End date","mission_count":"Mission count","completed_mission_count":"Completed mission count","project_id":"Project id"};
export const fieldTypes: Record<string, string> = {"label":"string","description":"string","placeholder":"string","status":"string","state_history":"StateTransition[]","allowed_transitions":"string[]","created_at":"datetime","updated_at":"datetime","last_event":"string","last_event_at":"datetime","searchQuery":"string","searchActive":"boolean","filters":"object[]","activeFilters":"object[]","filterCount":"number","page":"number","pageSize":"number","totalItems":"number","totalPages":"number","sprint_id":"string","title":"string","focus":"string","start_date":"string","end_date":"string","mission_count":"number","completed_mission_count":"number","project_id":"string"};
